import test from "node:test";
import assert from "node:assert/strict";
import {
	closeStore,
	exportBundle,
	importBundle,
	openStore,
	overview,
	related,
	remember,
	search,
} from "../lib/store.js";
import { describeCatalog, predicateCatalog, predicatesMatching, suggestPredicate } from "../lib/vocab.js";
import { runMetric } from "../lib/metrics.js";

/** @returns {{store: any}} fresh in-memory store. */
function fresh() {
	return { store: openStore(":memory:") };
}

test("the catalog exposes meaning, synonyms, and examples", () => {
	const allergy = predicateCatalog().find((entry) => entry.name === "allergy");
	assert.ok(allergy);
	assert.ok(allergy.about.includes("safety"));
	assert.ok(allergy.synonyms.includes("过敏"));
	assert.ok(allergy.examples.includes("花生"));
	assert.ok(describeCatalog().includes("synonyms:"));
	assert.ok(predicatesMatching("我对什么过敏").includes("allergy"));
	assert.ok(predicatesMatching("我住哪").includes("city"));
	assert.ok(suggestPredicate("allergies").includes("allergy"));
	assert.deepEqual(suggestPredicate("favoriteColor"), []);
});

test("a proposed fact is not live, searchable, or injected", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "allergy", object: "花生", status: "proposed" });
		assert.equal(overview(store).counts.facts, 0);
		assert.equal(search(store, { predicate: "allergy" }).length, 0);
		assert.equal(search(store, { predicate: "allergy", history: true }).length, 1);
		remember(store, { subject: "self", predicate: "allergy", object: "花生", status: "asserted" });
		assert.equal(overview(store).counts.facts, 1);
	} finally {
		closeStore(store);
	}
});

test("lineage survives a bundle round trip", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		const first = remember(a, {
			subject: "self",
			predicate: "name",
			object: "林舟",
			sourceKind: "user",
			sourceRef: "session:s1",
		});
		assert.equal(first.fact.source_kind, "user");
		assert.equal(first.fact.source_ref, "session:s1");
		assert.equal(typeof first.fact.confirmed_at, "string");

		const bundle = exportBundle(a);
		const exported = bundle.facts.find((fact) => fact.predicate === "name");
		assert.equal(exported.source_kind, "user");
		assert.equal(exported.source_ref, "session:s1");

		importBundle(b, bundle, { sourceRef: "bundle:test.json" });
		const imported = search(b, { predicate: "name" })[0];
		assert.equal(imported.source_kind, "user");
		assert.equal(imported.source_ref, "session:s1");
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("related walks one hop and keeps the edge direction", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "relation", object: "妈妈", qualifier: "mother" });
		remember(store, { subject: "妈妈", predicate: "allergy", object: "花生" });
		remember(store, { subject: "self", predicate: "works_on", object: "HarmonyGo" });
		remember(store, { subject: "HarmonyGo", predicate: "deadline", object: "2026-12-31" });

		const graph = related(store, { entity: "self", depth: 1 });
		const names = graph.nodes.map((node) => node.entity.name);
		assert.ok(names.includes("我"));
		assert.ok(names.includes("妈妈"));
		assert.ok(names.includes("HarmonyGo"));

		const mother = graph.nodes.find((node) => node.entity.name === "妈妈");
		assert.equal(mother.facts.some((fact) => fact.predicate === "allergy" && fact.object === "花生"), true);
		const incoming = mother.edges.find((edge) => edge.predicate === "relation");
		assert.equal(incoming.direction, "in");
		assert.equal(incoming.qualifier, "mother");

		const focused = related(store, { entity: "self", depth: 1, predicates: "relation" });
		assert.deepEqual(focused.nodes.map((node) => node.entity.name).sort(), ["妈妈", "我"]);
		assert.equal(focused.nodes.find((node) => node.entity.name === "妈妈").facts.length, 0);
	} finally {
		closeStore(store);
	}
});

test("import reports a conflicting single-valued fact instead of hiding it", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		remember(a, { subject: "self", predicate: "city", object: "上海" });
		remember(b, { subject: "self", predicate: "city", object: "北京" });
		const outcome = importBundle(b, exportBundle(a));
		assert.equal(outcome.conflicts.length, 1);
		assert.equal(outcome.conflicts[0].predicate, "city");
		assert.equal(outcome.conflicts[0].local, "北京");
		assert.equal(outcome.conflicts[0].incoming, "上海");
		assert.equal(outcome.conflicts[0].kept, "北京");
		assert.equal(search(b, { predicate: "city" })[0].object, "北京");
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("metrics compute age, day differences, and counts deterministically", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "birthday", object: "1990-04-02" });
		assert.equal(runMetric(store, { name: "age", subject: "self", now: "2026-04-01" }).value, 35);
		assert.equal(runMetric(store, { name: "age", subject: "self", now: "2026-04-02" }).value, 36);

		remember(store, { subject: "HarmonyGo", predicate: "deadline", object: "2026-12-31" });
		assert.equal(runMetric(store, { name: "days_until", subject: "HarmonyGo", now: "2026-12-01" }).value, 30);

		remember(store, { subject: "妈妈", predicate: "met_on", object: "2026-11-20" });
		assert.equal(runMetric(store, { name: "days_since", subject: "妈妈", now: "2026-11-25" }).value, 5);

		remember(store, { subject: "self", predicate: "works_on", object: "HarmonyGo" });
		assert.equal(runMetric(store, { name: "count", subject: "self", predicate: "works_on" }).value, 1);
	} finally {
		closeStore(store);
	}
});
